with flattened_attrs as (select id, effective_from, tier_limits, tier_prices, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, slice(tier_limits, 1, 2) as first_two_limits from price_tiers where effective_from < '2025-10-01') select id, effective_from, row_number() over w_part as row_seq, row_number() over w_part as row_seq_2, row_number() over w_part as seq_no, row_number() over (order by effective_from, id) as row_seq_3 from flattened_attrs window w_part as (order by effective_from desc, id)
